-- Phase 1 reference migration for PostgreSQL.
CREATE TABLE organizations (id VARCHAR(64) PRIMARY KEY, name VARCHAR(160) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE account_groups (id VARCHAR(64) PRIMARY KEY, organization_id VARCHAR(64) NOT NULL REFERENCES organizations(id), name VARCHAR(120) NOT NULL, description VARCHAR(500), capacity INTEGER NOT NULL DEFAULT 300, status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_group_org_name UNIQUE (organization_id, name));
CREATE TABLE gmail_accounts (id VARCHAR(64) PRIMARY KEY, organization_id VARCHAR(64) NOT NULL REFERENCES organizations(id), group_id VARCHAR(64) NOT NULL REFERENCES account_groups(id), email VARCHAR(320) NOT NULL, normalized_email VARCHAR(320) NOT NULL, account_type VARCHAR(32) NOT NULL DEFAULT 'GMAIL', lifecycle_status VARCHAR(48) NOT NULL DEFAULT 'SETUP_REQUIRED', readiness_status VARCHAR(48) NOT NULL DEFAULT 'READY_FOR_LOGIN', login_status VARCHAR(32) NOT NULL DEFAULT 'NOT_STARTED', gmail_status VARCHAR(32) NOT NULL DEFAULT 'NOT_CHECKED', recovery_hint VARCHAR(320) NOT NULL DEFAULT 'Not provided', two_fa_configured BOOLEAN NOT NULL DEFAULT FALSE, proxy_id VARCHAR(96), proxy_label VARCHAR(160), proxy_region VARCHAR(80), proxy_status VARCHAR(32) NOT NULL DEFAULT 'UNASSIGNED', profile_id VARCHAR(96), profile_storage_ref VARCHAR(500), profile_status VARCHAR(32) NOT NULL DEFAULT 'RESERVED', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_account_org_email UNIQUE (organization_id, normalized_email));
CREATE TABLE account_secrets (id VARCHAR(64) PRIMARY KEY, account_id VARCHAR(64) NOT NULL UNIQUE REFERENCES gmail_accounts(id) ON DELETE CASCADE, secret_ref VARCHAR(180) NOT NULL UNIQUE, encrypted_payload TEXT NOT NULL, key_version VARCHAR(32) NOT NULL DEFAULT 'v1', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE audit_events (id VARCHAR(64) PRIMARY KEY, organization_id VARCHAR(64) NOT NULL REFERENCES organizations(id), actor_id VARCHAR(96) NOT NULL, action VARCHAR(120) NOT NULL, target_type VARCHAR(48) NOT NULL, target_id VARCHAR(96) NOT NULL, result VARCHAR(32) NOT NULL, metadata_json JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE import_operations (id VARCHAR(64) PRIMARY KEY, organization_id VARCHAR(64) NOT NULL REFERENCES organizations(id), idempotency_key VARCHAR(120) NOT NULL, group_id VARCHAR(64) NOT NULL, imported INTEGER NOT NULL, duplicates INTEGER NOT NULL, invalid INTEGER NOT NULL, account_ids JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT uq_import_org_key UNIQUE (organization_id, idempotency_key));
